        page = self.page
        page.t("setTitle", "跨题重复问卷")
        # 两道题标题相同、选项完全相同；必填设置不同，保存后都要保留。
        page.t("addChoice", "满意度", ["满意", "一般"], True)
        page.t("addChoice", "满意度", ["满意", "一般"], False)

